#!/bin/bash\n# Jetson Orin Nano Super Hardware Optimization Script\n# Run this ONCE on your Jetson to configure optimal settings\n\necho \"======================================\"\necho \"Jetson Orin Nano Super Optimization\"\necho \"======================================\"\necho \"\"\n\n# Check if running on Jetson\nif ! grep -q \"Jetson\" /etc/nv_tegra_release 2>/dev/null; then\n    echo \"❌ This script must be run on a Jetson device!\"\n    exit 1\nfi\n\necho \"✓ Detected Jetson device\"\necho \"\"\n\n# Check for sudo\nif [[ $EUID -ne 0 ]]; then\n    echo \"❌ This script must be run with sudo\"\n    echo \"   Usage: sudo bash jetson_optimize.sh\"\n    exit 1\nfi\n\necho \"⚙️  Applying optimizations...\"\necho \"\"\n\n# 1. Set power mode to MAXN (max power = better performance)\necho \"[1/4] Setting power mode to MAXN (max performance)...\"\nif command -v nvpmodel &> /dev/null; then\n    nvpmodel -m0\n    echo \"✓ Power mode set to MAXN (25W sustained)\"\nelse\n    echo \"⚠ nvpmodel not found, skipping\"\nfi\necho \"\"\n\n# 2. Set CPU governor to performance\necho \"[2/4] Setting CPU governor to performance...\"\nfor cpu in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do\n    echo \"performance\" > \"$cpu\"\ndone\necho \"✓ CPU governor set to performance\"\necho \"\"\n\n# 3. Set max GPU clocks\necho \"[3/4] Setting max GPU clocks...\"\nif command -v jetson_clocks &> /dev/null; then\n    jetson_clocks\n    echo \"✓ Max clocks enabled\"\nelse\n    echo \"⚠ jetson_clocks not found, skipping\"\nfi\necho \"\"\n\n# 4. Configure zRAM for memory compression\necho \"[4/4] Checking memory compression (zRAM)...\"\nif swapon --show | grep -q zram; then\n    echo \"✓ zRAM already configured\"\nelse\n    echo \"ℹ zRAM not yet configured (optional enhancement)\"\n    echo \"  To enable: sudo apt install zram-config && sudo systemctl restart zram-config.service\"\nfi\necho \"\"\n\necho \"======================================\"\necho \"✓ Optimization Complete!\"\necho \"======================================\"\necho \"\"\necho \"Next steps:\"\necho \"1. Deploy optimized Flask app: python app.py\"\necho \"2. Monitor performance: tegrastats\"\necho \"3. Expected metrics:\"\necho \"   - GPU: 85-95%\"\necho \"   - RAM: 3-4GB / 8GB\"\necho \"   - Temp: < 70°C\"\necho \"\"\necho \"Note: Some settings revert on reboot.\"\necho \"To make permanent, add jetson_clocks to startup.\"\necho \"\"\n